```ts
import { goToFrame } from "@babylonjs/lite";
import type { AnimationGroup } from "@babylonjs/lite";

const DEFAULT_FRAME_RATE = 60;

export function skipToEnd(group: AnimationGroup): void {
    const end = (group._startTime ?? 0) + group.duration;

    // A looping clip would wrap back to its start at the end time, so turn looping off first.
    group.loopAnimation = false;

    // goToFrame pauses the group, syncs the controller and evaluates the pose once.
    // Use the owning manager's engine if there is one, so the pose is applied for real.
    const engine = group._animationManager?.engine;
    goToFrame(group, end * (group.frameRate || DEFAULT_FRAME_RATE), engine);

    // Frame/time conversion can be off by a rounding error, so pin the exact end time.
    group.currentTime = end;
    group.isPlaying = false;
}
```

I wrote `src/skip-to-end.ts`. It turns looping off, calls `goToFrame` at the clip's end (start time plus duration) so the last-keyframe pose is applied and the group is paused, then sets `currentTime` to exactly the end so the progress bar reads 100%.

Things I could not check, since I couldn't run anything:
- **Import:** I assumed `goToFrame` is exported from the `@babylonjs/lite` root. The declarations are per-file, so I couldn't confirm it.
- **Controller internals:** the controller's `tick` code isn't in what you sent. I'm assuming a non-playing, non-looping controller holds its time on later frames.
- **Looping:** the group stays non-looping afterwards. Restoring `loopAnimation = true` could make a later tick wrap the clip back to the start, so say if you want it restored on the next play.
